//! Emoji and text symbols for the picker (`tomboy emoji`, or "Emoji & Symbols" in the launcher).
//!
//! `emoji.tsv` is generated by `scripts/gen-emoji.py`: emoji, names and groups from Unicode's
//! `emoji-test.txt` (fully-qualified, no skin-tone variants), with extra search keywords from
//! Omarchy's emoji picker (`emojis.json`, MIT licence). `symbols.rs` adds arrows, math,
//! currency, typography, keyboard keys and Greek letters.

mod symbols;

use std::sync::OnceLock;

/// The section the hand-written symbols are listed under.
pub const TEXT_SYMBOLS: &str = "Text Symbols";

#[derive(Debug)]
pub struct Glyph {
    pub ch: &'static str,
    /// Lowercase, as Unicode names it ("grinning face").
    pub name: &'static str,
    /// "Smileys & Emotion", …, "Flags", then [`TEXT_SYMBOLS`].
    pub group: &'static str,
    pub keywords: &'static str,
}

impl Glyph {
    /// "Grinning face" for the footer.
    pub fn title(&self) -> String {
        let mut c = self.name.chars();
        c.next().map(|f| f.to_uppercase().chain(c).collect()).unwrap_or_default()
    }
}

/// Every emoji, then every text symbol, in Unicode order.
pub fn all() -> &'static [Glyph] {
    static ALL: OnceLock<Vec<Glyph>> = OnceLock::new();
    ALL.get_or_init(|| {
        let emoji = include_str!("emoji.tsv").lines().filter_map(|line| {
            let mut f = line.split('\t');
            Some(Glyph { ch: f.next()?, group: f.next()?, name: f.next()?, keywords: f.next().unwrap_or("") })
        });
        let text = symbols::SYMBOLS.iter().map(|&(ch, name, keywords)| Glyph { ch, name, group: TEXT_SYMBOLS, keywords });
        emoji.chain(text).collect()
    })
}

/// How well `g` matches the lowercased query words. Every word must hit; the score is the
/// weakest word's: whole name 6, a whole name word 5, a whole keyword 4, a name word prefix 3,
/// a keyword prefix 2, anywhere 1. So `lol` is 🤣 (keyword) before 🍭 (lollipop).
fn score(g: &Glyph, q: &str, words: &[&str]) -> Option<u32> {
    if g.name == q { return Some(6); }
    let name_words = || g.name.split(|c: char| !c.is_alphanumeric());
    let keywords = || g.keywords.split(' ');
    words.iter().map(|w| {
        if name_words().any(|n| n == *w) { Some(5) }
        else if keywords().any(|k| k == *w) { Some(4) }
        else if name_words().any(|n| n.starts_with(w)) { Some(3) }
        else if keywords().any(|k| k.starts_with(w)) { Some(2) }
        else if g.name.contains(w) || g.keywords.contains(w) || g.ch == *w { Some(1) }
        else { None }
    }).min().flatten()
}

/// Indices into [`all`] matching `query`, best first (shorter names, then Unicode order,
/// within a score), each raised by `boost(i)` (frecency). `heart` → ❤️ before 😍.
pub fn search(query: &str, boost: impl Fn(usize) -> u32) -> Vec<usize> {
    let q = query.trim().to_lowercase();
    let words: Vec<&str> = q.split_whitespace().collect();
    if words.is_empty() { return Vec::new(); }
    let mut hits: Vec<(u32, usize)> = all().iter().enumerate()
        .filter_map(|(i, g)| score(g, &q, &words).map(|s| (s * 1000 + boost(i), i)))
        .collect();
    let len = |i: usize| all()[i].name.len();
    hits.sort_by(|a, b| b.0.cmp(&a.0).then(len(a.1).cmp(&len(b.1))).then(a.1.cmp(&b.1)));
    hits.into_iter().map(|(_, i)| i).collect()
}

/// Index of the glyph `ch` in [`all`].
#[cfg(test)]
pub fn find(ch: &str) -> Option<usize> {
    all().iter().position(|g| g.ch == ch)
}

/// Does the launcher query ask for the picker? (`emoji`, `symbols`, `smiley`, …, 3+ letters.)
pub fn matches_command(query: &str) -> bool {
    let q = query.trim().to_lowercase();
    q.chars().count() >= 3 && ["emoji", "emojis", "symbols", "emoticons", "smiley", "emoji & symbols"]
        .iter().any(|w| w.starts_with(q.as_str()))
}

// ---- grid --------------------------------------------------------------------------------

/// One row of the picker grid.
#[derive(Clone, Debug, PartialEq)]
pub enum Row {
    Header(String),
    /// Up to [`COLS`] indices into [`all`].
    Cells(Vec<usize>),
}

pub const COLS: usize = 8;

/// Lay out sections (title, glyph indices) as grid rows.
pub fn grid(sections: Vec<(String, Vec<usize>)>) -> Vec<Row> {
    let mut rows = Vec::new();
    for (title, items) in sections.into_iter().filter(|(_, items)| !items.is_empty()) {
        rows.push(Row::Header(title));
        rows.extend(items.chunks(COLS).map(|c| Row::Cells(c.to_vec())));
    }
    rows
}

/// The empty-query sections: recently used, then every group in order.
pub fn browse(recent: Vec<usize>) -> Vec<(String, Vec<usize>)> {
    let mut sections: Vec<(String, Vec<usize>)> = vec![("Recently Used".into(), recent)];
    for (i, g) in all().iter().enumerate() {
        let open = sections.len() > 1;
        match sections.last_mut() {
            Some((title, items)) if open && title == g.group => items.push(i),
            _ => sections.push((g.group.to_string(), vec![i])),
        }
    }
    sections
}

/// A picked cell: (row, column) in the grid.
pub type Pos = (usize, usize);

/// The first cell of the grid.
pub fn first(rows: &[Row]) -> Option<Pos> {
    rows.iter().position(|r| matches!(r, Row::Cells(_))).map(|r| (r, 0))
}

fn cells(rows: &[Row], r: usize) -> usize {
    match rows.get(r) { Some(Row::Cells(c)) => c.len(), _ => 0 }
}

/// The glyph at `pos`.
pub fn at(rows: &[Row], pos: Pos) -> Option<usize> {
    match rows.get(pos.0) { Some(Row::Cells(c)) => c.get(pos.1).copied(), _ => None }
}

/// Move one cell (`dx`) or one row (`dy`), skipping headers; columns clamp to shorter rows and
/// left/right wrap across rows. Stays put at the ends.
pub fn step(rows: &[Row], (r, c): Pos, dx: i32, dy: i32) -> Pos {
    if dy != 0 {
        let mut next = r as i64;
        loop {
            next += dy as i64;
            if next < 0 || next >= rows.len() as i64 { return (r, c); }
            let n = cells(rows, next as usize);
            if n > 0 { return (next as usize, c.min(n - 1)); }
        }
    }
    if dx > 0 {
        if c + 1 < cells(rows, r) { return (r, c + 1); }
        let down = step(rows, (r, 0), 0, 1);
        return if down.0 != r { (down.0, 0) } else { (r, c) };
    }
    if dx < 0 {
        if c > 0 { return (r, c - 1); }
        let up = step(rows, (r, 0), 0, -1);
        return if up.0 != r { (up.0, cells(rows, up.0) - 1) } else { (r, c) };
    }
    (r, c)
}

/// The first cell of the next (`dir` > 0) or previous section.
pub fn section(rows: &[Row], (r, c): Pos, dir: i32) -> Pos {
    let headers: Vec<usize> = rows.iter().enumerate().filter(|(_, x)| matches!(x, Row::Header(_))).map(|(i, _)| i).collect();
    let current = headers.iter().rposition(|&h| h < r).unwrap_or(0);
    let target = if dir > 0 { current + 1 } else if current > 0 { current - 1 } else { return (r, c) };
    match headers.get(target) {
        Some(&h) if cells(rows, h + 1) > 0 => (h + 1, 0),
        _ => (r, c),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn first_hit(q: &str) -> &'static str { all()[search(q, |_| 0)[0]].ch }

    #[test]
    fn data_loads() {
        let all = all();
        assert!(all.len() > 1800, "{}", all.len());
        assert!(all.iter().all(|g| !g.ch.contains('\u{1F3FB}') && g.group != "Component"));
        assert!(all.iter().any(|g| g.group == TEXT_SYMBOLS));
        assert_eq!(all[0].ch, "😀");
        assert_eq!(all[0].title(), "Grinning face");
    }

    #[test]
    fn searches() {
        assert_eq!(first_hit("fire"), "🔥");
        assert_eq!(first_hit("thumbs"), "👍");
        assert_eq!(first_hit("lol"), "🤣");
        assert_eq!(first_hit("cmd"), "⌘");
        assert_eq!(first_hit("command"), "⌘");
        assert!(search("arrow", |_| 0).iter().any(|&i| all()[i].ch == "→"));
        assert_eq!(first_hit("grinning face"), "😀");
        assert_eq!(first_hit("heart"), "❤️");
        assert!(search("euro", |_| 0)[..3].iter().any(|&i| all()[i].ch == "€"));
        assert!(search("zzqqxx", |_| 0).is_empty());
        assert!(search("  ", |_| 0).is_empty());
        // A used emoji wins its tier.
        let heart = find("💜").unwrap();
        assert_eq!(all()[search("heart", |i| if i == heart { 150 } else { 0 })[0]].ch, "💜");
    }

    #[test]
    fn command_matches() {
        for q in ["emo", "Emoji", "emojis", "symbols", "smiley"] { assert!(matches_command(q), "{q}"); }
        for q in ["em", "emacs", "firefox"] { assert!(!matches_command(q), "{q}"); }
    }

    fn rows() -> Vec<Row> {
        grid(vec![("A".into(), (0..10).collect()), ("Empty".into(), vec![]), ("B".into(), vec![20, 21, 22])])
    }

    #[test]
    fn grid_layout() {
        let r = rows();
        assert_eq!(r.len(), 5); // A, 8 cells, 2 cells, B, 3 cells; the empty section is dropped
        assert_eq!(first(&r), Some((1, 0)));
        assert_eq!(at(&r, (2, 1)), Some(9));
        let b = browse(vec![]);
        assert_eq!(b[1].0, "Smileys & Emotion");
        assert_eq!(b.last().unwrap().0, TEXT_SYMBOLS);
    }

    #[test]
    fn grid_navigation() {
        let r = rows();
        assert_eq!(step(&r, (1, 7), 0, 1), (2, 1));   // down clamps to the shorter row
        assert_eq!(step(&r, (2, 1), 0, 1), (4, 1));   // skips header B
        assert_eq!(step(&r, (4, 2), 0, 1), (4, 2));   // bottom stays
        assert_eq!(step(&r, (1, 3), 0, -1), (1, 3));  // top stays
        assert_eq!(step(&r, (1, 7), 1, 0), (2, 0));   // right wraps
        assert_eq!(step(&r, (2, 0), -1, 0), (1, 7));  // left wraps back
        assert_eq!(step(&r, (1, 0), -1, 0), (1, 0));
        assert_eq!(section(&r, (2, 1), 1), (4, 0));
        assert_eq!(section(&r, (4, 2), -1), (1, 0));
        assert_eq!(section(&r, (4, 2), 1), (4, 2));
    }
}
